export async function selectFlight(b:Record<string,unknown>,u:TravelUser){const input=b.input as TripInput;
if(!input||input.transport!=='flight')throw Error('Choose flight transport before applying a flight quote.');
const d=db(),row=d.prepare('SELECT * FROM flight_search_selections WHERE id=? AND user_id=?').get(String(b.selectionId),u.id);
if(!row)throw Error('Flight quote not found for this session. Search again.');
if(canonical(route(input))!==canonical(JSON.parse(String(row.trip))))throw Error('The quote belongs to different dates, route or travellers. Search again.');
if(Date.now()-Date.parse(String(row.retrieved_at))>900000)throw Error('This search is over 15 minutes old. Refresh flight prices before selecting.');
if(!['group','per_person'].includes(String(b.basis)))throw Error('Choose whether the provider quote is a group or per-person amount.');
